import json,subprocess,sys
def gh(*args):
 return json.loads(subprocess.check_output(["gh",*args],text=True))
repo="unbrowse-ai/unbrowse-core"
root="repos/"+repo
sha=gh("api",root+"/branches/staging")["commit"]["sha"]
runs=gh("api","-X","GET",root+"/actions/runs","-f","head_sha="+sha,"-f","event=push","-f","per_page=100")["workflow_runs"]
ok=True
for name in ("CI","Coverage","Promotion gate"):
 row=next((r for r in runs if r["name"]==name),{})
 print(sha,name,row.get("conclusion") or row.get("status") or "missing",row.get("html_url",""))
 ok &= row.get("conclusion")=="success"
if gh("api",root+"/branches/staging")["commit"]["sha"]!=sha: sys.exit("staging moved during verification")
if not ok: sys.exit(1)
